// broadcast.js — run from tron_contracts/
require('dotenv').config();
const { TronWeb } = require('tronweb');

const tronWeb = new TronWeb({
    fullHost: 'https://nile.trongrid.io',
    privateKey: process.env.PRIVATE_KEY_NILE,
});

const CONTRACT = 'TXnUujd5RRr671K7tsYWhw1cHT5suK51jd';
const SELECTOR =
    'execute(address,uint256,bytes,uint256,uint256,(bytes,string,uint256,uint256,bytes32,bytes32))';
const PARAMETER = "";

(async () => {
    const owner = tronWeb.defaultAddress.base58;

    // rawParameter takes the pre-encoded hex directly, so tronweb's own
    // encoder — and its struct handling — stays out of the path. 
    const { transaction } = await tronWeb.transactionBuilder.triggerSmartContract(
        CONTRACT,
        SELECTOR,
        { feeLimit: 20_000_000, rawParameter: PARAMETER },
        [],
        owner,
    );

    const signed = await tronWeb.trx.sign(transaction);
    console.log(await tronWeb.trx.sendRawTransaction(signed));
})();